// Pulls modern photoreal AI-generator images (added 2026-08-16 for the
// "modern generator" corpus expansion -- see manifest.json provenanceNotes
// and COMPETITION_EXECUTION_PLAN.md) from Rapidata's per-model text-to-image
// human-preference datasets on HF. Each of these datasets is a pairwise A/B
// comparison (image1 vs image2, generated by model1 vs model2) collected via
// the Rapidata annotation platform; we only keep the image whose model
// matches this domain's targetModel (the other side of the comparison is a
// different generator entirely and is ignored). All three datasets share the
// exact same {prompt, image1, image2, model1, model2, ...} schema, license
// (CDLA-Permissive-2.0 -- commercial use allowed, no NonCommercial
// restriction), and datasets-server access pattern, so one script drives all
// three domains from a specifications table (same pattern as
// scripts/prepare-genimage-replacement.mjs).
//
// ai/gpt-image        <- Rapidata/OpenAI-4o_t2i_human_preference   (regular 70/15/15 split)
// ai/imagen4           <- Rapidata/Imagen4_t2i_human_preference     (FULLY HOLDOUT -- see split script)
// ai/recraft-v3         <- Rapidata/Recraft-v3-24-7-25_t2i_human_preference (FULLY HOLDOUT -- see split script)
//
// imagen4 and recraft-v3 are two of this expansion's >=2 fully-held-out
// "unseen generator" domains (distinct from the pre-existing flux-krea /
// nano-banana fully-holdout sources) -- chosen because Rapidata's datasets
// give ample volume (13k-65k rows) to guarantee a meaningful holdout-only
// sample size without ever appearing in train/calibration.
import { createHash } from 'node:crypto';
import { mkdir, readdir, readFile, writeFile } from 'node:fs/promises';
import { resolve } from 'node:path';
import sharp from 'sharp';

const LICENSE = 'cdla-permissive-2.0';
const output = resolve(process.argv[2] || '.bench-data/realimage-broad-v1/_staging');
const concurrency = Number(process.env.PROOFMARK_FETCH_CONCURRENCY || 3);

const specifications = [
  {
    key: 'gpt-image',
    dataset: 'Rapidata/OpenAI-4o_t2i_human_preference',
    targetModel: '4o-26-3-25',
    generatorLabel: 'GPT-Image (gpt-4o native image generation, 26-3-25 snapshot)',
    count: 260,
  },
  {
    key: 'imagen4',
    dataset: 'Rapidata/Imagen4_t2i_human_preference',
    targetModel: 'imagen-4.0-ultra-generate-exp-05-20',
    generatorLabel: 'Google Imagen 4 Ultra (experimental, 05-20)',
    count: 220,
  },
  {
    key: 'recraft-v3',
    dataset: 'Rapidata/Recraft-v3-24-7-25_t2i_human_preference',
    targetModel: 'recraft-v3-24-7-25',
    generatorLabel: 'Recraft v3 (24-7-25 snapshot)',
    count: 220,
  },
];

const manifest = [];

for (const specification of specifications) {
  const directory = `${output}/ai/${specification.key}`;
  await mkdir(directory, { recursive: true });
  const existingFileNames = new Set(await readdir(directory));
  if (existingFileNames.size >= specification.count) {
    console.log(`${specification.key}: already has ${existingFileNames.size}/${specification.count} staged, skipping (resumed run)`);
    continue;
  }
  const remaining = specification.count - existingFileNames.size;
  console.log(`${specification.key}: resuming, ${existingFileNames.size} already staged, need ${remaining} more`);
  // Checkpoint lives OUTSIDE the domain directory -- split-realimage-broad-v1.mjs
  // treats every file under _staging/<label>/<domain>/ as an image to copy,
  // so a bookkeeping file in there would get copied into train/calibration/
  // holdout as if it were a corpus image.
  await mkdir(`${output}/_checkpoints`, { recursive: true });
  const checkpointPath = `${output}/_checkpoints/${specification.key}.json`;
  const exactHashes = new Set();
  let newlyAdded = 0;
  let offset = await readCheckpoint(checkpointPath);
  if (offset > 0) console.log(`${specification.key}: resuming row scan from offset=${offset} (checkpoint)`);
  const pageLength = 100;
  let consecutiveEmpty = 0;

  while (newlyAdded < remaining && consecutiveEmpty < 8) {
    const rows = await fetchRows(specification.dataset, offset, pageLength);
    offset += pageLength;
    await writeFile(checkpointPath, JSON.stringify({ offset })).catch(() => {});
    if (rows.length === 0) {
      consecutiveEmpty += 1;
      continue;
    }
    const candidates = [];
    for (const item of rows) {
      const row = item.row;
      if (row.model1 === specification.targetModel && row.image1) candidates.push(row.image1);
      if (row.model2 === specification.targetModel && row.image2) candidates.push(row.image2);
    }
    if (candidates.length === 0) {
      consecutiveEmpty += 1;
      continue;
    }
    consecutiveEmpty = 0;
    for (let cursor = 0; cursor < candidates.length && newlyAdded < remaining; cursor += concurrency) {
      const batch = candidates.slice(cursor, cursor + concurrency);
      const downloaded = await Promise.all(batch.map((candidate) => downloadCandidate(candidate).catch(() => null)));
      for (const item of downloaded) {
        if (!item || newlyAdded >= remaining || exactHashes.has(item.sha256)) continue;
        exactHashes.add(item.sha256);
        const fileName = `${item.sha256.slice(0, 16)}.${item.extension}`;
        const record = {
          label: 'ai',
          domain: specification.key,
          fileName,
          sourceDataset: specification.dataset,
          sourceLicense: LICENSE,
          generator: specification.generatorLabel,
          width: item.width,
          height: item.height,
          format: item.format,
          sha256: item.sha256,
        };
        manifest.push(record);
        if (existingFileNames.has(fileName)) continue; // identical content already staged from a prior run -- nothing to do
        await writeFile(`${directory}/${fileName}`, item.bytes);
        existingFileNames.add(fileName);
        newlyAdded += 1;
      }
      await delay(150);
    }
    process.stderr.write(`\r${specification.key}: ${existingFileNames.size}/${specification.count} (scanned offset=${offset})`);
  }
  process.stderr.write('\n');
  const finalCount = (await readdir(directory)).length;
  if (finalCount < specification.count) {
    throw new Error(`Only staged ${finalCount}/${specification.count} images for ${specification.key} from ${specification.dataset}`);
  }
  console.log(`${specification.key}: staged ${finalCount} images from ${specification.dataset}`);
}

await writeFile(`${output}/rapidata-modern-generators-pull-manifest.json`, `${JSON.stringify({ license: LICENSE, generatedAt: new Date().toISOString(), rows: manifest }, null, 2)}\n`);
console.log(`Prepared ${manifest.length} licensed modern-generator images in ${output}`);

async function fetchRows(dataset, offset, length) {
  const parameters = new URLSearchParams({ dataset, config: 'default', split: 'train', offset: String(offset), length: String(length) });
  const response = await fetchWithRetry(`https://datasets-server.huggingface.co/rows?${parameters}`);
  const payload = await response.json();
  return payload.rows || [];
}

async function downloadCandidate(imageField) {
  const response = await fetchWithRetry(imageField.src);
  const bytes = Buffer.from(await response.arrayBuffer());
  if (bytes.length < 1_000 || bytes.length > 25_000_000) return null;
  const metadata = await sharp(bytes).metadata();
  if (!metadata.width || !metadata.height || Math.min(metadata.width, metadata.height) < 256) return null;
  const sha256 = createHash('sha256').update(bytes).digest('hex');
  return {
    bytes,
    width: metadata.width,
    height: metadata.height,
    format: metadata.format,
    extension: extensionFor(metadata.format),
    sha256,
  };
}

function extensionFor(format) {
  if (format === 'jpeg') return 'jpg';
  if (['png', 'webp', 'avif', 'gif'].includes(format)) return format;
  return 'img';
}

async function fetchWithRetry(url) {
  let lastError;
  for (let attempt = 1; attempt <= 24; attempt += 1) {
    try {
      const response = await fetch(url);
      if (response.ok) return response;
      lastError = new Error(`HTTP ${response.status}`);
      const retryAfter = Number(response.headers.get('retry-after') || 0);
      const isRateLimited = response.status === 429;
      const backoff = isRateLimited
        ? Math.min(8_000 * attempt, 45_000) + Math.random() * 2_000
        : Math.max(attempt * 1_000, 1_500);
      await delay(Math.max(retryAfter * 1_000, backoff));
      continue;
    } catch (error) {
      lastError = error;
      await delay(Math.min(2_000 * attempt, 20_000));
    }
  }
  throw lastError || new Error(`Unable to fetch ${url}`);
}

function delay(milliseconds) {
  return new Promise((resolveDelay) => setTimeout(resolveDelay, milliseconds));
}

async function readCheckpoint(path) {
  try {
    const raw = await readFile(path, 'utf8');
    const parsed = JSON.parse(raw);
    return Number(parsed.offset) || 0;
  } catch {
    return 0;
  }
}
